from pathlib import Path
poses={'bongeka':['normal','smiling','laughing','thinking','celebrating','holding-heart','surprised','annoyed'],'bongumusa':['normal','smiling','laughing','holding-heart','celebrating','waving','romantic','surprised']}
def character(person,pose):
 girl=person=='bongeka'; skin='#754632' if girl else '#70432f'; hair=''
 if girl:
  hair='<ellipse cx="90" cy="72" rx="55" ry="62" fill="#29201f"/>'
  for x,y,r in [(40,30,18),(62,18,18),(88,14,18),(116,21,19),(134,39,18),(140,65,16),(139,89,17),(135,116,16),(39,63,17),(38,88,16),(43,112,15)]: hair+=f'<circle cx="{x}" cy="{y}" r="{r}" fill="#302422"/><path d="M{x-6} {y-6}q12 -6 11 8" fill="none" stroke="#493531" stroke-width="2"/>'
 else: hair='<path d="M47 58Q45 15 91 16Q132 16 132 57Z" fill="#211e23"/><path d="M47 43Q92 26 135 43L149 54Q99 65 47 55Z" fill="#27242a"/><path d="M79 31l21 -3" stroke="#b797b2" stroke-width="2"/>'
 raised=pose in ['celebrating','waving']; arm='<path d="M57 135L34 '+('87' if raised else '182')+'M122 135L147 '+('83' if raised else '179')+'" stroke="'+skin+'" stroke-width="16" stroke-linecap="round"/>'
 eyes='<ellipse cx="72" cy="68" rx="5" ry="6" fill="#241d1d"/><ellipse cx="107" cy="68" rx="5" ry="6" fill="#241d1d"/><circle cx="73" cy="66" r="1.7" fill="white"/><circle cx="108" cy="66" r="1.7" fill="white"/>'
 if pose in ['laughing','celebrating']: eyes='<path d="M65 68q7 -10 14 0M100 68q7 -10 14 0" fill="none" stroke="#291d1a" stroke-width="3" stroke-linecap="round"/>'
 mouth='<path d="M74 85Q90 104 107 85Z" fill="#fff6e9"/><path d="M77 94q13 10 27 -1" stroke="#b45d63" stroke-width="3" fill="none"/>'
 if pose in ['thinking','annoyed']: mouth='<path d="M81 91q10 -4 20 0" fill="none" stroke="#392421" stroke-width="3"/>'
 if pose=='surprised': mouth='<ellipse cx="90" cy="91" rx="6" ry="8" fill="#38211e"/>'
 outfit='<path d="M58 122Q90 115 123 122L130 158H52Z" fill="#fffaf1"/><path d="M59 158H120V172H59Z" fill="'+skin+'"/><path d="M57 171H123L127 210H92L89 184L85 210H53Z" fill="#658698"/><path d="M89 174v25M60 183l15 3M107 186l13 -3" stroke="#adc0c8" fill="none" stroke-width="2"/>' if girl else '<path d="M56 119H124L132 176H48Z" fill="#be3948"/><path d="M72 120v56M106 120v56" stroke="#27272b" stroke-width="17"/><path d="M73 120q17 14 35 0" stroke="#fff1e9" fill="none" stroke-width="5"/><path d="M49 176H132L130 216H96L90 188L84 216H50Z" fill="#292831"/>'
 heart='<path d="M90 157C58 133 63 116 80 123L90 132L100 123C118 117 125 134 90 157Z" fill="#d5637b" stroke="#f6b8bf" stroke-width="2"/>' if pose in ['holding-heart','romantic'] else ''
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 180 290"><g>{hair}<path d="M70 103v23q20 15 40 0v-23" fill="{skin}"/>{arm}<path d="M65 204v47M112 204v47" stroke="{skin}" stroke-width="21" stroke-linecap="round"/><path d="M56 245h20v17H56M103 245h20v17h-20" fill="#fff5eb"/><path d="M55 258q-12 5 -10 17h35v-17ZM102 258v17h38q1 -12 -18 -17Z" fill="'+('#bc354e' if girl else '#e68cb4')+'"/><path d="M51 266h24M109 266h22" stroke="#fff1e7" stroke-width="2"/>'+outfit+f'<ellipse cx="90" cy="69" rx="40" ry="45" fill="{skin}"/><ellipse cx="50" cy="76" rx="7" ry="10" fill="{skin}"/><ellipse cx="130" cy="76" rx="7" ry="10" fill="{skin}"/>'+('<path d="M49 49q21 -3 31 -24q21 24 49 24" stroke="#302422" stroke-width="17" fill="none"/><path d="M50 36l6 -10 7 10 -8 5Z" fill="#fff8ec"/><circle cx="49" cy="89" r="7" stroke="#dcb96b" stroke-width="2" fill="none"/><circle cx="131" cy="89" r="7" stroke="#dcb96b" stroke-width="2" fill="none"/>' if girl else '<path d="M49 40q41 -20 87 4l13 11q-53 -1 -99 3Z" fill="#24212a"/>')+f'<path d="M63 56q8 -4 17 -1M101 55q9 -4 17 1" fill="none" stroke="#36231f" stroke-width="3" stroke-linecap="round"/>{eyes}<path d="M89 71l-3 9h7" stroke="#583322" fill="none" stroke-width="2"/>{mouth}{heart}</g></svg>'
for person,states in poses.items():
 for pose in states: Path(f'assets/characters/{person}/{pose}.svg').write_text(character(person,pose))
a=character('bongeka','holding-heart').split('<g>')[1].split('</g>')[0]; b=character('bongumusa','romantic').split('<g>')[1].split('</g>')[0]
Path('assets/characters/couple/together.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 310"><ellipse cx="180" cy="285" rx="150" ry="12" fill="#e9cfc1"/><g transform="translate(32 10)">'+a+'</g><g transform="translate(158 10)">'+b+'</g><g fill="#c85b71" font-size="28"><text x="160" y="35">♡</text><text x="25" y="90">♡</text><text x="325" y="95">♡</text></g></svg>')
Path('assets/images/memory-placeholder.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="600" height="600"><defs><linearGradient id="a" x2="1" y2="1"><stop stop-color="#f3d8cb"/><stop offset="1" stop-color="#e8b9c4"/></linearGradient></defs><rect width="600" height="600" fill="url(#a)"/><circle cx="300" cy="265" r="190" fill="#fff3e8"/><path d="M300 355C110 220 220 120 300 215C380 120 490 220 300 355" fill="#c85b71"/><text x="300" y="432" text-anchor="middle" fill="#68463e" font-family="Georgia" font-size="37">Our little love story</text><text x="300" y="474" text-anchor="middle" fill="#936d62" font-family="Georgia" font-size="20">Every piece belongs together.</text></svg>')
